    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        uint balBefore = address(c).balance;
        uint recipientBefore = recipient.balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address owner = c.owner();
        if (msg.sender == owner) {
            assert(!reverted && recipient.balance == recipientBefore + balBefore && address(c).balance == 0);
        } else {
            assert(reverted && address(c).balance == balBefore && recipient.balance == recipientBefore);
        }
    }

    receive() external payable {}
}

