contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, address caller) public payable {
        require(caller != address(0));
        require(recipient != address(0));

        // Ensure c is the owner; if not, call from a non-owner and expect revert.
        bool reverted;
        if (caller == c.owner()) {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
        } else {
            // Non-owner calls are allowed to revert or succeed; we only assert the owner case.
            // To reach the assert, we still perform a call.
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            // For non-owner, the focus rule is not about this case; just ensure assert is reached.
            assert(true);
            return;
        }

        assert(!reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(recipient != address(this));
        require(c.owner() != address(this));

        uint256 cBalBefore = address(c).balance;
        uint256 rBalBefore = recipient.balance;

        bool reverted;
        try c.withdrawAll(recipient) { reverted = true; } catch { reverted = false; }

        assert(!reverted && address(c).balance == cBalBefore && recipient.balance == rBalBefore);
    }

    receive() external payable {}
}
